// Generated by scripts/build_demo.py from assets/settings.js
'use strict';
let draftConfig=null,settingsDirty=false,settingsBusy=false,settingsBaseline='';
const settingMessage=(text,error=false)=>{const el=$('#settingsMessage');el.hidden=false;el.textContent=text;el.classList.toggle('failure',error);};
function markDirty(){settingsDirty=true;$('#discardSettings').hidden=true;$('#settingsMessage').hidden=true;}
function buildDeviceRows(){
  $('#deviceRows').replaceChildren();
  draftConfig.cameras.forEach((camera,index)=>{
    const row=document.createElement('div');row.className='device-row';
    const cell=(input)=>{const wrapper=document.createElement('label');wrapper.append(input);row.append(wrapper);};
    const enabled=document.createElement('input');enabled.type='checkbox';enabled.dataset.field='enabled';enabled.checked=camera.enabled!==false;enabled.setAttribute('aria-label','啟用設備 '+(index+1));enabled.onchange=()=>{camera.enabled=enabled.checked;markDirty();};cell(enabled);
    for(const [key,title,type] of [['label','設備名稱','text'],['ip','來源 IPv4','text'],['ftp_port','FTP 接收埠','number']]){
      const input=document.createElement('input');input.type=type;input.dataset.field=key;input.value=camera[key]??'';input.setAttribute('aria-label',title+' '+(index+1));
      if(type==='number'){input.min='1';input.max='65535';input.placeholder='預設 '+$('#cfgFtp').value;}
      else{input.required=true;input.maxLength=key==='label'?40:15;}
      input.oninput=()=>{camera[key]=type==='number'?(input.value===''?null:Number(input.value)):input.value;markDirty();};cell(input);
    }
    const tools=document.createElement('div');tools.className='rowtools';
    for(const [text,label,action,disabled] of [
      ['↑','上移設備',()=>{[draftConfig.cameras[index-1],draftConfig.cameras[index]]=[camera,draftConfig.cameras[index-1]];},index===0],
      ['↓','下移設備',()=>{[draftConfig.cameras[index+1],draftConfig.cameras[index]]=[camera,draftConfig.cameras[index+1]];},index===draftConfig.cameras.length-1],
      ['移除','移除設備設定，保留照片',()=>draftConfig.cameras.splice(index,1),draftConfig.cameras.length===1]
    ]){const b=document.createElement('button');b.type='button';b.textContent=text;b.title=label;b.setAttribute('aria-label',label+' '+(index+1));b.disabled=disabled;b.onclick=()=>{syncDeviceInputs();action();markDirty();buildDeviceRows();};tools.append(b);}
    row.append(tools);$('#deviceRows').append(row);
  });
  $('#deviceCount').textContent=draftConfig.cameras.length+' / 10';$('#addDevice').disabled=draftConfig.cameras.length>=10;
}
function fillSettings(config){
  draftConfig=JSON.parse(JSON.stringify(config));
  for(const c of draftConfig.cameras){c.enabled=c.enabled!==false;c.ftp_port=c.ftp_port??null;}
  for(const [id,key,fallback] of [['cfgFtp','ftp_port',2121],['cfgWeb','web_port',8080],['cfgMax','max_photos',1000],['cfgStale','stale_seconds',300],['cfgHost','ftp_host','0.0.0.0']])$('#'+id).value=draftConfig[key]??fallback;
  buildDeviceRows();
}
function collectSettings(){
  syncDeviceInputs();
  return {...draftConfig,ftp_host:$('#cfgHost').value.trim(),ftp_port:Number($('#cfgFtp').value),web_port:Number($('#cfgWeb').value),max_photos:Number($('#cfgMax').value),stale_seconds:Number($('#cfgStale').value),cameras:draftConfig.cameras.map(c=>({...c,label:c.label.trim(),ip:c.ip.trim()}))};
}
function syncDeviceInputs(){
  [...$('#deviceRows').children].forEach((row,i)=>{const c=draftConfig.cameras[i];for(const input of row.querySelectorAll('input')){const key=input.dataset.field;c[key]=key==='enabled'?input.checked:key==='ftp_port'?(input.value===''?null:Number(input.value)):input.value;}});
}
function closeSettings(){if(settingsBusy)return;if(settingsDirty||JSON.stringify(collectSettings())!==settingsBaseline){settingMessage('尚有未儲存修改。請先儲存，或選擇捨棄修改。');$('#discardSettings').hidden=false;return;}$('#settingsDialog').close();}
$('#settings').onclick=async()=>{
  if(settingsBusy)return;settingsBusy=true;$('#settings').disabled=true;
  try{const response=await window.demoAPI('/api/config',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error('無法讀取設定');fillSettings(await response.json());settingsBaseline=JSON.stringify(collectSettings());settingsDirty=false;$('#settingsMessage').hidden=true;$('#discardSettings').hidden=true;$('#settingsPath').textContent='資料位置：'+(latestData?.data_path||'讀取中');$('#settingsDialog').showModal();}
  catch(e){toast('無法開啟設定，請確認服務仍在執行。');}finally{settingsBusy=false;$('#settings').disabled=false;}
};
$('#closeSettings').onclick=closeSettings;
$('#discardSettings').onclick=()=>{settingsDirty=false;$('#settingsDialog').close();};
$('#settingsDialog').addEventListener('cancel',e=>{e.preventDefault();closeSettings();});
$('#settingsDialog').addEventListener('click',e=>{if(e.target===$('#settingsDialog'))closeSettings();});
for(const id of ['cfgFtp','cfgWeb','cfgMax','cfgStale','cfgHost'])$('#'+id).oninput=()=>{markDirty();if(id==='cfgFtp')for(const input of $('#deviceRows').querySelectorAll('[data-field="ftp_port"]'))input.placeholder='預設 '+$('#cfgFtp').value;};
$('#addDevice').onclick=()=>{if(draftConfig.cameras.length>=10)return;syncDeviceInputs();draftConfig.cameras.push({id:crypto.randomUUID(),label:'設備 '+(draftConfig.cameras.length+1),ip:'',ftp_port:null,enabled:true});markDirty();buildDeviceRows();};
$('#settingsForm').onsubmit=async e=>{
  e.preventDefault();if(settingsBusy)return;settingsBusy=true;
  const controls=[...$('#settingsForm').querySelectorAll('button,input')],disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);
  try{
    const response=await window.demoAPI('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(collectSettings()),signal:AbortSignal.timeout(10000)});
    const body=await response.json();if(!response.ok)throw Error(body.error||'無法儲存設定');
    draftConfig=body.config;settingsBaseline=JSON.stringify(collectSettings());settingsDirty=false;$('#discardSettings').hidden=true;
    settingMessage(body.local_saved?'已套用展示設定，僅影響此瀏覽器。正式程式與設備設定均未變更。':'已套用到本次展示；瀏覽器限制儲存，因此重新整理後不會保留。');$('#pendingSettings').hidden=true;
  }catch(error){settingMessage(error.message||'儲存失敗，請確認服務仍在執行。',true);}
  finally{controls.forEach((c,i)=>c.disabled=disabled[i]);settingsBusy=false;}
};
$('#exportConfig').onclick=()=>{
  if(!$('#settingsForm').reportValidity())return;
  const blob=new Blob([JSON.stringify(collectSettings(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chingtech-config-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);settingMessage('已匯出表單設定。備份不含照片；尚未儲存的修改仍需按儲存設定。');
};
$('#importConfig').onclick=()=>$('#importFile').click();
$('#importFile').onchange=async e=>{
  const file=e.target.files[0];e.target.value='';if(!file)return;
  try{
    if(file.size>65536)throw Error('設定檔不可超過 64 KB');const value=JSON.parse(await file.text());
    if(!value||!Array.isArray(value.cameras)||value.cameras.length<1||value.cameras.length>10||!value.cameras.every(c=>c&&typeof c.ip==='string'&&typeof c.label==='string'))throw Error('需包含 1～10 台設備，且每台均有 IP 與名稱');
    fillSettings(value);markDirty();settingMessage('已載入備份到表單。請確認 IP、接收埠及保留上限，再按儲存；重開程式後套用。');
  }catch(error){settingMessage('匯入失敗：'+error.message,true);}
};
